function plan(title, level, summary, prerequisites, outcomes, sequence, visual, practice, misconceptions, sourceKeys, depth = 'core', reviewFocus = 'Record GPU model, architecture, toolkit, compiler and driver; recheck supported behavior before implementation.') {
  return { title, level, blueprint: { summary, outcomes, prerequisites, sequence,
    visual: { type: visual[0], question: visual[1], interaction: visual[2] },
    practice: { task: practice[0], success: practice[1] }, misconceptions,
    sources: sourceKeys.map(key => gpuSources[key].url), depth, reviewFocus } };
}

